export function deepTopicFor(module,track,article) {
  const matches=tutorialDeepTopics.filter(topic=>(!topic.modules||topic.modules.includes(module.id))&&(!topic.tracks||topic.tracks.includes(track.slug))&&topic.match.test(article.title));
  return matches.find(topic=>topic.tracks) || matches[0];
}
